er{background:#fcfdf9}.overview-action>span:nth-child(2){flex:1}.overview-action strong{display:block;font-size:13px;font-weight:600}.overview-action small{display:block;margin-top:7px;color:#748066;font-size:11px;line-height:1.5}.overview-action>svg{color:#97a482}.crm-workspace-note{border:1px solid #e3e7d8;background:#f0f2e8;padding:28px;border-radius:14px;align-self:start}.note-tag{color:#8d987b;font-size:10px;letter-spacing:1.3px}.crm-workspace-note h3{font-size:22px;font-weight:550;letter-spacing:-.6px;line-height:1.4;margin:20px 0 14px}.crm-workspace-note p{color:#6d795f;line-height:1.9;font-size:12px}.crm-workspace-note>div{display:flex;gap:8px;align-items:center;font-size:10px;color:#879772;border-top:1px solid #e1e6d6;margin-top:25px;padding-top:18px}.note-dot{width:5px;height:5px;border-radius:50%;background:#8ca36d}.crm-dashboard-details{margin-top:24px;display:grid;grid-template-columns:1fr 1fr;gap:20px}.crm-dashboard-details:deep(>section){background:white;border:1px solid #e5e8dc;border-radius:13px;padding:22px;font-size:12px;line-height:1.7}.crm-dashboard-details:deep(h3){margin:0 0 12px;font-size:15px}.crm-dashboard-details:deep(button){margin:6px 6px 0 0;font-size:11px;padding:9px 12px}.crm-dashboard-details:deep(p){margin:8px 0;color:#748066}.upcoming-list{list-style:none;padding:0;margin:14px 0}.upcoming-list li{padding:14px 0;border-bottom:1px solid #e1e6d6}.upcoming-list span{display:block;font-size:11px;color:#7b8969}.upcoming-list strong{display:block;margin-top:6px;font-size:13px;font-weight:550}.agenda-link{display:flex;align-items:center;gap:12px;border:0;border-top:1px solid #dfe5d3;background:none;color:#5e7434;font-size:12px;font-weight:600;width:100%;padding:18px 0 0;margin-top:24px;cursor:pointer}.crm-dashboard-details:empty{display:none}@media(max-width:1050px){.crm-overview-grid{grid-template-columns:1fr}.crm-dashboard-details{grid-template-columns:1fr}}@media(max-width:650px){.crm-welcome{padding:24px}.crm-welcome h2{font-size:24px}.welcome-mark{display:none}.crm-metrics{grid-template-columns:1fr}.crm-metric{padding:19px}.overview-action{padding:20px}.crm-workspace-note{display:none}}
</style>
